import json, requests, os

NOTION_TOKEN = os.environ['NOTION_TOKEN']
PARENT_PAGE_ID = 'ваш_id_страницы'

headers = {
    'Authorization': f'Bearer {NOTION_TOKEN}',
    'Content-Type': 'application/json',
    'Notion-Version': '2026-03-11'
}

# 1. Читаем JSON-файл
with open('notion_pages/brochure.json', 'r', encoding='utf-8') as f:
    content = json.load(f)

# 2. Создаём или очищаем страницу
# Для простоты: создаём новую страницу
page_data = {
    'parent': { 'page_id': PARENT_PAGE_ID },
    'properties': {
        'title': { 'title': [{ 'text': { 'content': content['title'] } }] }
    },
    'children': [
        {
            'object': 'block',
            'type': 'heading_1',
            'heading_1': { 'rich_text': [{ 'text': { 'content': content['subtitle'] } }] }
        },
        # ... остальные блоки (через цикл по content['sections'])
    ]
}

response = requests.post('https://api.notion.com/v1/pages', headers=headers, json=page_data)
print(response.json())
